const jobs = $input.first().body.jobs || [];
return jobs.map(job => ({
  jobId: `remotive_${job.id}`,
  source: 'Remotive',
  title: job.title,
  company: job.company_name,
  url: job.url,
  description: job.description || '',
  isRemote: true,
  postedAt: new Date(job.publication_date).toISOString()
}));

const jobs = Array.isArray($input.first().body) ? $input.first().body : [];
return jobs.slice(1).map(job => ({
  jobId: `remoteok_${job.id || job.slug}`,
  source: 'RemoteOK',
  title: job.position,
  company: job.company,
  url: job.url,
  description: job.description || '',
  isRemote: true,
  postedAt: new Date(job.epoch * 1000).toISOString()
}));

const jobs = $input.first().body.data || [];
return jobs.map(job => ({
  jobId: `arbeitnow_${job.slug}`,
  source: 'Arbeitnow',
  title: job.title,
  company: job.company_name,
  url: job.url,
  description: job.description || '',
  isRemote: !!job.remote,
  postedAt: new Date(job.created_at).toISOString()
}));

const KEYWORD_INCLUDE = ['cloud engineer', 'associate cloud engineer', 'cloud support engineer', 'devops engineer', 'site reliability engineer', 'cloud infrastructure engineer', 'cloud engineer intern', 'entry level', 'junior', 'associate', 'junior cloud', 'junior devops', 'sre', 'associate devops', 'associate infrastructure', 'aws', 'azure', 'gcp', 'kubernetes', 'docker'];
const KEYWORD_EXCLUDE = ['senior', 'staff', 'principal', 'lead', 'manager', 'director', 'head of', 'chief', 'vp ', 'vice president', 'architect'];
const jobs = $input.first().json;
return jobs.filter(job => {
  if (!job.isRemote) return false;
  const titleLower = (job.title || '').toLowerCase();
  const descLower = (job.description || '').toLowerCase();
  const searchText = titleLower + ' ' + descLower;
  const hasInclude = KEYWORD_INCLUDE.some(kw => searchText.includes(kw));
  if (!hasInclude) return false;
  const hasExclude = KEYWORD_EXCLUDE.some(kw => searchText.includes(kw));
  if (hasExclude) return false;
  return true;
});

const filteredJobs = $input.first().json;
const seenRows = $input.last().json;
const seenIds = new Set(seenRows.map(row => row.jobId));
return filteredJobs.filter(job => !seenIds.has(job.jobId));

